import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { usageFixture } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { cleanupExpiredRateLimits } from "@/lib/rate-limit-jobs";

describe.runIf(databaseTestsEnabled)("daily rate-limit cleanup", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
  });
  afterAll(async () => {
    await fixture?.close();
  });

  it("cleans multiple batches while preserving recent and active budgets and skipping locked rows", async () => {
    const now = Date.now();
    const expired = new Date(now - 2 * 86400000);
    const locked = randomUUID();
    const recent = randomUUID();
    const active = randomUUID();
    await fixture.db.rateLimitBucket.createMany({
      data: [
        ...Array.from({ length: 501 }, () => ({
          scope: randomUUID(),
          operation: "campaign",
          cleanupAt: expired,
        })),
        {
          id: locked,
          scope: randomUUID(),
          operation: "campaign",
          cleanupAt: expired,
        },
        {
          id: recent,
          scope: randomUUID(),
          operation: "campaign",
          cleanupAt: new Date(now - 3600000),
        },
        {
          id: active,
          scope: randomUUID(),
          operation: "campaign",
          admissions: [new Date(now)],
          cleanupAt: new Date(now + 60000),
        },
      ],
    });
    await fixture.db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "RateLimitBucket" WHERE id=${locked}::uuid FOR UPDATE`;
      expect(await cleanupExpiredRateLimits()).toEqual({ deleted: 501 });
      expect(
        (await fixture.db.rateLimitBucket.findMany())
          .map((row) => row.id)
          .sort(),
      ).toEqual([locked, recent, active].sort());
    });
    expect(await cleanupExpiredRateLimits()).toEqual({ deleted: 1 });
    expect(await cleanupExpiredRateLimits()).toEqual({ deleted: 0 });
  });
});
